            });

            // Populate units
            const unitsList = productToEdit.definedUnits ? productToEdit.definedUnits.map(u => u.unitName) : (productToEdit.saleUnits ? productToEdit.saleUnits.split(',').map(s => s.trim()) : []);
            setSelectedUnits(unitsList);

            const details: Record<string, ProductUnitDefinition> = {};
