        setUnitDetails(prev => ({
            ...prev,
            [unit]: {
                ...prev[unit],
                [field]: value
            }
        }));
    };

    const handleClose = () => {
        setIsClosing(true);
        setTimeout(() => {
            onClose();
            setIsClosing(false);
        }, 300);
    };

    const handleSave = () => {
