                        <div>
                            <label className={labelClasses}>Remarks</label>
                            <textarea name="remarks" value={formData.remarks} onChange={handleChange} rows={3} className={commonInputClasses}></textarea>
                        </div>
                    </div>
                </div>

                <div className={`flex justify-end items-center p-6 border-t rounded-b-lg ${theme === 'dark' ? 'border-slate-700 bg-black/50' : 'border-slate-200 bg-slate-100'}`}>
                    <button onClick={handleClose} className={`px-6 py-2.5 text-sm font-medium border rounded-md shadow-sm mr-3 ${theme === 'dark' ? 'text-slate-300 bg-transparent border-slate-600 hover:bg-slate-700' : 'text-slate-700 bg-white border-slate-300 hover:bg-slate-50'}`}>
                        Cancel
                    </button>
                    <button onClick={handleSave} className="px-6 py-2.5 text-sm font-semibold text-slate-900 bg-yellow-500 border border-transparent rounded-md shadow-sm hover:bg-yellow-600 flex items-center">
                        <Icon name="check-circle" className="h-4 w-4 mr-2" />
                        Update
                    </button>
                </div>
            </div>
        </div>
    );
};

export default EditProductModal;
