                                name="invoiceNumber" 
                                placeholder="Invoice #"
                                className={`mt-1 block w-full rounded-md shadow-sm sm:text-sm px-3 py-2 border ${commonInputClasses} ${commonFocusClasses}`}
                                value={invoiceNumber}
                                onChange={(e) => setInvoiceNumber(e.target.value)}
